import * as PIXI from 'pixi.js';

export class FreeGameCounter extends PIXI.Container {
    private currentFreeGameText: PIXI.Text;
    private totalFreeGameText: PIXI.Text;

    constructor() {
        super();

        const background = new PIXI.Graphics();
        background.roundRect(0, 0, 210, 62, 10);
        background.fill({ color: 0x252b48, alpha: 0.94 });
        background.stroke({ color: 0xffd166, width: 2 });

        const currentLabel = this.createText('FREE GAME', 12, 8, 12);
        const totalLabel = this.createText('TOTAL', 112, 8, 12);
        this.currentFreeGameText = this.createText('0', 65, 24, 22);
        this.totalFreeGameText = this.createText('0', 165, 24, 22);

        this.addChild(background, currentLabel, totalLabel, this.currentFreeGameText, this.totalFreeGameText);
    }

    public initialize(currentFreeGame: number, totalFreeGame: number): void {
        this.updateCounter(currentFreeGame, totalFreeGame);
    }

    public updateCounter(currentFreeGame: number, totalFreeGame: number): void {
        this.currentFreeGameText.text = String(currentFreeGame);
        this.totalFreeGameText.text = String(totalFreeGame);
    }

    private createText(text: string, x: number, y: number, fontSize: number): PIXI.Text {
        const label = new PIXI.Text({
            text,
            style: new PIXI.TextStyle({
                fill: '#ffffff',
                fontSize,
                fontWeight: 'bold',
                align: 'center',
            }),
        });
        label.anchor.set(0.5, 0);
        label.position.set(x, y);
        return label;
    }
}
