import { MatchCount, PayoutModel } from '../models/PayoutModel';

export interface WinPattern {
    id: number;
    cells: Array<[number, number]>;
}

export interface WinEvaluation {
    totalWin: number;
    winningLines: number[];
    wins: WinLineData[];
}

export interface WinningSymbolData {
    symbolId: number;
    rowId: number;
    reelId: number;
}

export interface WinLineData {
    lineId: number;
    symbols: WinningSymbolData[];
    winSum: number;
}

const WIN_PATTERNS: WinPattern[] = [
    { id: 0, cells: [[0, 0], [1, 0], [2, 0], [3, 0], [4, 0]] },
    { id: 1, cells: [[0, 1], [1, 1], [2, 1], [3, 1], [4, 1]] },
    { id: 2, cells: [[0, 2], [1, 2], [2, 2], [3, 2], [4, 2]] },
    { id: 3, cells: [[0, 0], [1, 1], [2, 2]] },
    { id: 4, cells: [[0, 2], [1, 1], [2, 0], [3, 1], [4, 2]] },
];

export class WinEvaluator {
    public static evaluate(matrix: number[][], bet = 1): WinEvaluation {
        const winningLines: number[] = [];
        const wins: WinLineData[] = [];
        let totalWin = 0;

        for (const pattern of WIN_PATTERNS) {
            const firstCell = pattern.cells[0];
            const firstValue = matrix[firstCell[0]]?.[firstCell[1]];

            if (firstValue === undefined) {
                continue;
            }

            const symbols: WinningSymbolData[] = [];
            for (const [reel, row] of pattern.cells) {
                if (matrix[reel]?.[row] !== firstValue) {
                    break;
                }
                symbols.push({
                    symbolId: firstValue,
                    rowId: row,
                    reelId: reel,
                });
            }

            const matchCount = symbols.length;
            if (matchCount < 3) {
                continue;
            }

            winningLines.push(pattern.id);
            const winSum = PayoutModel.getWinAmount(firstValue, matchCount as MatchCount, bet);
            totalWin += winSum;
            wins.push({
                lineId: pattern.id,
                symbols,
                winSum,
            });
        }

        return { totalWin, winningLines, wins };
    }
}
