import { Game, type GameSceneId } from './Game';
import { BaseGameScene } from './scene/BaseGameScene';
import { FreeGameScene } from './scene/FreeGameScene';
import type { GameScene } from './scene/GameScene';

export class SlotGame extends Game {
    protected registerScence(sceneId: GameSceneId, totalFreeGames = 0): GameScene {
        if (sceneId === 'Free_Game') {
            return new FreeGameScene(this, totalFreeGames);
        }
        return new BaseGameScene(this);
    }
}
