import * as PIXI from 'pixi.js';

interface TimerEntry {
    durationMs: number;
    elapsedMs: number;
    tick?: (ticker: PIXI.Ticker) => void;
    resolve?: () => void;
    reject?: (reason: Error) => void;
}

export class Timer {
    private readonly timers = new Map<number, TimerEntry>();
    private nextTimerId = 0;

    public addTimer(durationMs: number): number {
        if (!Number.isFinite(durationMs) || durationMs < 0) {
            throw new RangeError('Timer duration must be a finite, non-negative number.');
        }

        const timerId = this.nextTimerId++;
        this.timers.set(timerId, { durationMs, elapsedMs: 0 });
        return timerId;
    }

    public startTimer(timerId: number): Promise<void> {
        const entry = this.timers.get(timerId);
        if (!entry) {
            throw new Error(`Timer ${timerId} does not exist.`);
        }
        if (entry.tick) {
            throw new Error(`Timer ${timerId} has already been started.`);
        }

        if (entry.durationMs === 0) {
            this.timers.delete(timerId);
            return Promise.resolve();
        }

        return new Promise<void>((resolve, reject) => {
            entry.resolve = resolve;
            entry.reject = reject;
            entry.tick = (ticker: PIXI.Ticker): void => {
                entry.elapsedMs += ticker.deltaMS;

                if (entry.elapsedMs >= entry.durationMs) {
                    PIXI.Ticker.shared.remove(entry.tick!);
                    this.timers.delete(timerId);
                    resolve();
                }
            };

            PIXI.Ticker.shared.add(entry.tick);
        });
    }

    public removeTimer(timerId: number): boolean {
        const entry = this.timers.get(timerId);
        if (!entry) {
            return false;
        }

        if (entry.tick) {
            PIXI.Ticker.shared.remove(entry.tick);
            entry.reject?.(new Error(`Timer ${timerId} was removed.`));
        }

        this.timers.delete(timerId);
        return true;
    }
}

export const gameTimer = new Timer();
