import * as PIXI from 'pixi.js';
import 'pixi.js/text';
import { SlotGame } from './SlotGame';
import { AssetPreLoader } from './assets/AssetPreLoader';

async function bootstrap() {
    const app = new PIXI.Application();

    await app.init({
        width: 1280,
        height: 720,
        backgroundColor: 0x1a1a2e,
    });
(globalThis as unknown as { __PIXI_APP__: typeof app }).__PIXI_APP__ = app;
const container = document.getElementById('game-container');
    if (container) {
        container.appendChild(app.canvas);
    } else {
        document.body.appendChild(app.canvas);
    }
    new AssetPreLoader();
    const gameRoot = new SlotGame(app.stage);


    const resizeGame = () => {
        const width = Math.max(1, container?.clientWidth ?? window.innerWidth);
        const height = Math.max(1, container?.clientHeight ?? window.innerHeight);
        app.renderer.resize(width, height);
        gameRoot.resize(width, height);
    };
    window.addEventListener('resize', resizeGame);

    if (container) {
        new ResizeObserver(resizeGame).observe(container);
    }
    resizeGame();

    console.log('[Engine Bootstrapped]: PixiJS Canvas Attached successfully.');
}

bootstrap().catch(console.error);