import { EventDispather, GameEvents } from "../core/EventDispather";
import { WinEvaluator, type WinLineData } from './WinEvaluator';

export interface SpinRequest {
    betAmount: number;
    lines: number;
}

export interface SpinResponse {
    matrix: number[][]; // e.g. 3x5 reel matrix
    totalWin: number;
    wins: WinLineData[];
    freeSpinsTriggered: boolean;
}
export class NetworkService {
    private eventBus = EventDispather.getInstance();

    public async getDummayData(request: SpinRequest): Promise<SpinResponse> {
        return new Promise((resolve, reject) => {
            const matrix = [
                [0, 1, 2],
                [3, 4, 5],
                [6, 7, 0],
                [1, 2, 3],
                [4, 5, 6],
            ];
            const evaluation = WinEvaluator.evaluate(matrix, request.betAmount);
            const dummyResponse: SpinResponse = {
                matrix,
                totalWin: evaluation.totalWin,
                wins: evaluation.wins,
                freeSpinsTriggered: false
            };
            resolve(dummyResponse);

        });
    }

    // Mock API Call to Casino Backend
    public async requestSpinData(request: SpinRequest): Promise<SpinResponse> {
        return new Promise((resolve, reject) => {
            // Basic validation
            if (request.betAmount <= 0) {
                reject(new Error("Invalid bet amount"));
                return;
            }

            // Network delay simulation (500ms)
            setTimeout(() => {
                const rows = 3;
                const cols = 5;
                const symbolPool = [0, 1, 2, 3, 4, 5, 6, 7];
                const randomMatrix = Array.from({ length: cols }, () =>
                    Array.from({ length: rows }, () =>
                        symbolPool[Math.floor(Math.random() * symbolPool.length)]
                    )
                );
                // Keep the mock response representative of its previous guaranteed-win behavior.
                const winningSymbol = Math.floor(Math.random() * 6);
                const winningRow = Math.floor(Math.random() * rows);
                for (let reel = 0; reel < 3; reel += 1) {
                    randomMatrix[reel][winningRow] = winningSymbol;
                }
                const evaluation = WinEvaluator.evaluate(randomMatrix, request.betAmount);
                const mockResponse: SpinResponse = {
                    matrix: randomMatrix,
                    totalWin: evaluation.totalWin,
                    wins: evaluation.wins,
                    freeSpinsTriggered: true
                };
                this.eventBus.emit(GameEvents.SPIN_RESPONSE_RECEIVED, mockResponse);
                resolve(mockResponse);
            }, 500); 
        });
    }
}