import * as PIXI from 'pixi.js';

export class FreeGameIntro extends PIXI.Container {
    private readonly totalText: PIXI.Text;

    constructor(onContinue: () => void) {
        super();
        this.visible = false;
        this.eventMode = 'static';
        this.hitArea = new PIXI.Rectangle(0, 0, 700, 720);

        const backdrop = new PIXI.Graphics();
        backdrop.rect(0, 0, 700, 720);
        backdrop.fill({ color: 0x000000, alpha: 0.72 });

        const panel = new PIXI.Graphics();
        panel.roundRect(100, 235, 500, 250, 24);
        panel.fill({ color: 0x252b48 });
        panel.stroke({ color: 0xffd166, width: 3 });

        const heading = this.createText('CONGRATULATIONS!', 350, 275, 34, '#ffd166');
        this.totalText = this.createText('', 350, 340, 24, '#ffffff');
        const button = this.createButton('START FREE GAMES', 350, 415, onContinue);

        this.addChild(backdrop, panel, heading, this.totalText, button);
    }

    public show(totalFreeGames: number): void {
        this.totalText.text = `You won ${totalFreeGames} free games!`;
        this.visible = true;
    }

    public hide(): void {
        this.visible = false;
    }

    private createText(text: string, x: number, y: number, fontSize: number, fill: string): PIXI.Text {
        const label = new PIXI.Text({
            text,
            style: new PIXI.TextStyle({ fill, fontSize, fontWeight: 'bold', align: 'center' }),
        });
        label.anchor.set(0.5);
        label.position.set(x, y);
        return label;
    }

    private createButton(text: string, x: number, y: number, onClick: () => void): PIXI.Container {
        const button = new PIXI.Container();
        const background = new PIXI.Graphics();
        background.roundRect(0, 0, 250, 48, 10);
        background.fill({ color: 0x00b894 });
        const label = this.createText(text, 125, 24, 17, '#ffffff');

        button.position.set(x - 125, y - 24);
        button.eventMode = 'static';
        button.cursor = 'pointer';
        button.addChild(background, label);
        button.on('pointerdown', onClick);
        return button;
    }
}
