import { AssetLoader } from "./AssetLoader";
import { AssetPreloading } from "./AssetPreloading";
export type AssetData = {
    alias: string;
    spritePath: string;
    jsonPath?: string;
};
export class AssetPreLoader extends AssetPreloading {

    loadDesktopAssets(): void {
    }
    loadMobileAssets(): void {
    }
    loadGameAssets(): void {
        AssetLoader.load("symbols-sheet", AssetLoader.getAssetUrl('graphics/symbols.png'), AssetLoader.getAssetUrl('graphics/symbols.json'), 'init');
        AssetLoader.load("game-backgrounds", AssetLoader.getAssetUrl('graphics/bg.png'), AssetLoader.getAssetUrl('graphics/bg.json'), 'init');
        AssetLoader.loadSpine('win-star', AssetLoader.getAssetUrl('spine/star.json'), AssetLoader.getAssetUrl('spine/star.atlas'), 'init');
        AssetLoader.load("symbolsWin", AssetLoader.getAssetUrl('graphics/symbolWin.png'), AssetLoader.getAssetUrl('graphics/symbolWin.json'), 'init');

    }
}