import * as PIXI from 'pixi.js';
import { EventDispather, GameEvents } from '../core/EventDispather';

export class ResponsiveGameContainer extends PIXI.Container {
    private readonly resizeHandler = (screenWidth: number, screenHeight: number): void => {
        this.resize(screenWidth, screenHeight);
    };

    constructor(
        public readonly gameAreaW: number = 700,
        public readonly gameAreaH: number = 720,
        public readonly scaleMode: 'contain' | 'cover' = 'contain'
    ) {
        super();
        EventDispather.getInstance().on(GameEvents.GAME_RESIZED, this.resizeHandler);
    }

    public dispose(): void {
        EventDispather.getInstance().off(GameEvents.GAME_RESIZED, this.resizeHandler);
    }

    public resize(viewportWidth: number, viewportHeight: number): void {
        const scale = this.scaleMode === 'cover'
            ? Math.max(viewportWidth / this.gameAreaW, viewportHeight / this.gameAreaH)
            : Math.min(viewportWidth / this.gameAreaW, viewportHeight / this.gameAreaH);

        this.scale.set(scale);
        this.position.set(
            (viewportWidth - this.gameAreaW * scale) / 2,
            (viewportHeight - this.gameAreaH * scale) / 2
        );
    }
}
