import * as PIXI from 'pixi.js';
import { Game } from '../Game';
import { GameState } from '../models/GameStateModel';
import { ResponsiveGameContainer } from '../views/ResponsiveGameContainer';
import { ReelAnimationManager } from '../reels/ReelAnimationManager';
import { ReelContainer } from '../reels/ReelContainer';
import { SymbolManager } from '../symbols/SymbolManager';
import { AssetLoader } from '../assets/AssetLoader';
import { ButtonPanel } from '../views/ButtonPanel';
import { GamePlayRequest } from '../services/GamePlayRequest';
import { GameEvents } from '../core/EventDispather';
import { BottomBar } from '../views/BottomBar';
import { GameRound } from '../rounds/GameRound';
import { WinEvaluationRound } from '../rounds/WinEvaluationRound';
import { SymbolConfig } from '../symbols/SymbolConfig';
import { SpinResponse } from '../services/NetworkService';
import { SpineWinEffect } from '../winCelebration/SpineWinEffect';
import { GameBackground } from '../views/GameBackground';
import { PromoMessages } from '../views/PromoMessages';

interface SharedGameSceneComponents {
    gameBackground: GameBackground;
    buttonPanel: ButtonPanel;
    bottomBar: BottomBar;
    promoMessages: PromoMessages;
    symbolManager: SymbolManager;
    animationManager: ReelAnimationManager;
    reelContainer: ReelContainer;
    winCelebration: SpineWinEffect;
}

interface SharedGameSceneResources {
    backgroundLayer: ResponsiveGameContainer;
    gameLayer: ResponsiveGameContainer;
    bottomBarLayer: ResponsiveGameContainer;
    buttonPanelLayer: ResponsiveGameContainer;
    bigWinLayer: ResponsiveGameContainer;
    foregroundLayer: ResponsiveGameContainer;
    components?: SharedGameSceneComponents;
}

export class GameScene extends PIXI.Container {
    private static readonly resourcesByGame = new WeakMap<Game, SharedGameSceneResources>();

    public game: Game;
    public sceneId: string;
    protected backgroundLayer: ResponsiveGameContainer;
    protected gameLayer: ResponsiveGameContainer;
    protected bottomBarLayer: ResponsiveGameContainer;
    protected buttonPanelLayer: ResponsiveGameContainer;
    protected bigWinLayer: ResponsiveGameContainer;
    protected foregroundLayer: ResponsiveGameContainer;
    protected buttonPanel!: ButtonPanel;
    protected bottomBar!: BottomBar;
    private winCelebration!: SpineWinEffect;

    private symbolManager!: SymbolManager;
    private animationManager!: ReelAnimationManager;
    private reelContainer!: ReelContainer;
    private autoPlayEnabled = false;
    private autoPlayTimer: ReturnType<typeof setTimeout> | undefined;
    protected gameRounds: GameRound[] = [];
    private gameBackground!: GameBackground;
    private promoMessages!: PromoMessages;
    protected isFreeGame = false;
    private isInitialized = false;
    private spinRequest!: GamePlayRequest;
    private readonly sharedResources: SharedGameSceneResources;

    private readonly stateChangedHandler = (): void => {
        if (this.game.stateModel.currentState === GameState.SPINNING) {
            this.game.balance -= this.game.bet;
            this.bottomBar.setBalance(this.game.balance);
            this.bottomBar.hide();
        } else if (this.game.stateModel.currentState === GameState.IDLE && this.autoPlayEnabled) {
            this.scheduleAutoPlaySpin();
        }
    };
    private readonly startWinPresentationHandler = (): void => {
        void this.startWinPresentaion();
    };
    private readonly spinResponseHandler = (response: SpinResponse): void => {
        this.injectReponse(response);
    };

    constructor(
        game: Game,
        sceneId: string = 'Base_Game',
    ) {
        super();
        this.game = game;
        this.sceneId = sceneId;
        this.game.stage.addChild(this);

        let sharedResources = GameScene.resourcesByGame.get(game);
        if (!sharedResources) {
            sharedResources = {
                backgroundLayer: new ResponsiveGameContainer(700, 720, 'cover'),
                gameLayer: new ResponsiveGameContainer(),
                bottomBarLayer: new ResponsiveGameContainer(),
                buttonPanelLayer: new ResponsiveGameContainer(),
                bigWinLayer: new ResponsiveGameContainer(),
                foregroundLayer: new ResponsiveGameContainer(),
            };
            GameScene.resourcesByGame.set(game, sharedResources);
        }
        this.sharedResources = sharedResources;
        this.backgroundLayer = sharedResources.backgroundLayer;
        this.gameLayer = sharedResources.gameLayer;
        this.bottomBarLayer = sharedResources.bottomBarLayer;
        this.buttonPanelLayer = sharedResources.buttonPanelLayer;
        this.bigWinLayer = sharedResources.bigWinLayer;
        this.foregroundLayer = sharedResources.foregroundLayer;
        this.addChild(
            this.backgroundLayer,
            this.gameLayer,
            this.bottomBarLayer,
            this.buttonPanelLayer,
            this.bigWinLayer,
            this.foregroundLayer,
        );
    }
    protected addComponents(): void {
        this.isFreeGame = this.sceneId === 'Free_Game';
        let components = this.sharedResources.components;
        if (!components) {
            this.registerBackgrounds();
            // this.registerGameTitle();
            this.registerPromoMessage();
            this.registerSymbols();
            this.registerReelContainers();
            this.registerButtonPanels();
            this.registerBottomBar();
            this.buttonPanel.position.set(0, 550);
            const reelGridWidth = this.reelContainer.reels.length * SymbolConfig.REEL_WIDTH;
            this.reelContainer.position.set((this.gameLayer.gameAreaW - reelGridWidth) / 2, 180);
            this.bottomBar.position.set(0, 640);
            this.winCelebration = new SpineWinEffect();
            this.winCelebration.position.set(this.bigWinLayer.gameAreaW / 2, this.bigWinLayer.gameAreaH / 2);
            this.bigWinLayer.addChild(this.winCelebration);

            components = {
                gameBackground: this.gameBackground,
                buttonPanel: this.buttonPanel,
                bottomBar: this.bottomBar,
                promoMessages: this.promoMessages,
                symbolManager: this.symbolManager,
                animationManager: this.animationManager,
                reelContainer: this.reelContainer,
                winCelebration: this.winCelebration,
            };
            this.sharedResources.components = components;
        }

        this.gameBackground = components.gameBackground;
        this.buttonPanel = components.buttonPanel;
        this.bottomBar = components.bottomBar;
        this.promoMessages = components.promoMessages;
        this.symbolManager = components.symbolManager;
        this.animationManager = components.animationManager;
        this.reelContainer = components.reelContainer;
        this.winCelebration = components.winCelebration;
        void this.gameBackground.show(this.isFreeGame, 0);
        this.bottomBar.setBalance(this.game.balance);
        this.bottomBar.setBet(this.game.bet);
        this.buttonPanel.setCallbacks(
            () => { void this.toggleBackground(); },
            (enabled) => this.setAutoPlayEnabled(enabled),
        );
        this.registerCommands();
    }
    protected registerBottomBar(): void {
        // Register bottom panels here
        this.bottomBar = new BottomBar();
        this.bottomBarLayer.addChild(this.bottomBar);
    }
    protected registerCommands(): void {
        // Register game command here
        this.spinRequest = new GamePlayRequest(this.game, this.animationManager);
        this.game.eventDispatcher.on(GameEvents.STATE_CHANGED, this.stateChangedHandler);
        this.game.eventDispatcher.on(GameEvents.START_WIN_PRESENTATION, this.startWinPresentationHandler);
        this.game.eventDispatcher.on(GameEvents.SPIN_RESPONSE_RECEIVED, this.spinResponseHandler);
    }
    protected injectReponse(gameResponse: SpinResponse): void {
        this.game.activeResponse = gameResponse;
        this.game.roundWin = this.game.activeResponse?.totalWin;
    }
    protected registerBackgrounds(): void {
        this.isFreeGame = this.sceneId === 'Free_Game';
        this.gameBackground = new GameBackground(
            new PIXI.Sprite(AssetLoader.getTexture('game-backgrounds', 'blue_sky')),
            new PIXI.Sprite(AssetLoader.getTexture('game-backgrounds', 'sunset_sky')),
            this.isFreeGame,
            this.backgroundLayer.gameAreaW,
            this.backgroundLayer.gameAreaH,
        );
        this.backgroundLayer.addChild(this.gameBackground);
    }
    protected registerGameTitle(): void {
        const title = new PIXI.Text({
            text: 'Slot Demo',
            style: new PIXI.TextStyle({
                fill: '#ffd166',
                fontSize: 36,
                fontWeight: 'bold',
            }),
        });
        title.anchor.set(0.5);
        title.position.set(350, 95);
        this.gameLayer.addChild(title);
    }
    protected registerPromoMessage(): void {
        this.promoMessages = new PromoMessages(700, 44, 'alpha');
        this.promoMessages.position.set(0, 125);

        for (const message of ['This is promo 1', 'Demo Slot', 'This is promo 2']) {
            const text = new PIXI.Text({
                text: message,
                style: new PIXI.TextStyle({
                    fill: '#ffd166',
                    fontSize: 36,
                    fontWeight: 'bold',
                    align: 'center',
                }),
            });
            text.anchor.set(0.5);
            text.position.set(350, 22);
            this.promoMessages.addPromo(text);
        }

        this.foregroundLayer.addChild(this.promoMessages);
        this.promoMessages.start();
    }
    protected registerSymbols(): void {
        this.symbolManager = new SymbolManager();
        const spriteKey: string = "symbols-sheet";
        const winSpriteKey: string = "symbolsWin";

        this.symbolManager.registerSymbol(0, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_santa_hat")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_santa_hat")]),
        );
        this.symbolManager.registerSymbol(1, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_candy_cane")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_candy_cane")]),
        );
        this.symbolManager.registerSymbol(2, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bauble")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_bauble")]),
        );
        this.symbolManager.registerSymbol(3, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_gingerbread")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_gingerbread")]),
        );
        this.symbolManager.registerSymbol(4, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_stocking")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_stocking")]),
        );
        this.symbolManager.registerSymbol(5, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_bell")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_bell")]),
        );
        this.symbolManager.registerSymbol(6, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_snow_globe")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_snow_globe")]),
        );
        this.symbolManager.registerSymbol(7, new PIXI.Sprite(AssetLoader.getTexture(spriteKey, "symbol_star_tree")),
            new PIXI.AnimatedSprite([AssetLoader.getTexture(winSpriteKey, "symbol_star_tree")]),
        );
        // Register scene symbols here
    }
    protected registerButtonPanels(): void {
        // Register button panels here
        this.buttonPanel = new ButtonPanel(
            () => { void this.toggleBackground(); },
            (enabled) => this.setAutoPlayEnabled(enabled)

        );
        this.buttonPanelLayer.addChild(this.buttonPanel);
    }
    protected registerReelContainers(): void {
        // Register reel containers here
        this.reelContainer = new ReelContainer(this.symbolManager, 5, 3);
        this.animationManager = new ReelAnimationManager(this.reelContainer);
        this.gameLayer.addChild(this.reelContainer);
    }

    public init(): void {
        if (!this.isInitialized) {
            this.addComponents();
            this.isInitialized = true;
        }
        this.game.stateModel.transitionTo(GameState.IDLE);
    }

    public dispose(): void {
        this.game.eventDispatcher.off(GameEvents.STATE_CHANGED, this.stateChangedHandler);
        this.game.eventDispatcher.off(GameEvents.START_WIN_PRESENTATION, this.startWinPresentationHandler);
        this.game.eventDispatcher.off(GameEvents.SPIN_RESPONSE_RECEIVED, this.spinResponseHandler);
        this.spinRequest?.dispose();
        this.buttonPanel?.setAutoPlayEnabled(false);
        if (this.autoPlayTimer !== undefined) {
            clearTimeout(this.autoPlayTimer);
            this.autoPlayTimer = undefined;
        }
        for (const layer of [
            this.backgroundLayer,
            this.gameLayer,
            this.bottomBarLayer,
            this.buttonPanelLayer,
            this.bigWinLayer,
            this.foregroundLayer,
        ]) {
            if (layer.parent === this) {
                layer.removeFromParent();
            }
        }
        this.removeFromParent();
        this.destroy({ children: true });
    }
    private async toggleBackground(): Promise<void> {
        this.isFreeGame = !this.isFreeGame;
        await this.gameBackground.show(this.isFreeGame);
    }
    private setAutoPlayEnabled(enabled: boolean): void {
        this.autoPlayEnabled = enabled;
        if (this.autoPlayTimer !== undefined) {
            clearTimeout(this.autoPlayTimer);
            this.autoPlayTimer = undefined;
        }
        if (enabled && this.game.stateModel.currentState === GameState.IDLE) {
            this.scheduleAutoPlaySpin();
        }
    }
    private scheduleAutoPlaySpin(): void {
        if (this.autoPlayTimer !== undefined) {
            clearTimeout(this.autoPlayTimer);
        }
        this.autoPlayTimer = setTimeout(() => {
            this.autoPlayTimer = undefined;
            if (this.autoPlayEnabled && this.game.stateModel.currentState === GameState.IDLE) {
                this.game.eventDispatcher.emit(GameEvents.USER_CLICK_SPIN);
            }
        }, 1000);
    }
    private async startWinPresentaion(): Promise<void> {
        this.game.stateModel.transitionTo(GameState.EVALUATING);
        this.gameRounds = [
            new WinEvaluationRound(this.reelContainer, this.game.activeResponse?.wins ?? [])
        ];
        for (const round of this.gameRounds) {
            await round.init();
        }
        this.bottomBar.setBalance(this.bottomBar.getBalance() + this.game.roundWin);
        if (this.game.roundWin > 0) {
            this.bottomBar.showWin(this.game.roundWin);
            //void this.winCelebration.play();
        }

    }
}