import { Game } from '../Game';
import { FreeGameCounter } from '../views/FreeGameCounter';
import { FreeGameIntro } from '../views/FreeGameIntro';
import { FreeGameOutro } from '../views/FreeGameOutro';
import { GameScene } from './GameScene';

export class FreeGameScene extends GameScene {
    private readonly totalFreeGames: number;
    private freeGameCounter!: FreeGameCounter;
    private freeGameIntro!: FreeGameIntro;
    private freeGameOutro!: FreeGameOutro;

    constructor(game: Game, totalFreeGames: number) {
        super(game, 'Free_Game');
        this.totalFreeGames = totalFreeGames;
    }

    protected override addComponents(): void {
        super.addComponents();

        this.freeGameCounter = new FreeGameCounter();
        this.freeGameCounter.position.set(245, 12);
        this.gameLayer.addChild(this.freeGameCounter);

        this.freeGameIntro = new FreeGameIntro(() => this.freeGameIntro.hide());
        this.foregroundLayer.addChild(this.freeGameIntro);

        this.freeGameOutro = new FreeGameOutro(() => this.game.endFreeGame());
        this.foregroundLayer.addChild(this.freeGameOutro);
    }

    public override init(): void {
        super.init();
        this.freeGameCounter.initialize(1, this.totalFreeGames);
        this.freeGameIntro.show(this.totalFreeGames);
    }

    public updateCounter(currentFreeGame: number, totalFreeGame: number): void {
        this.freeGameCounter.updateCounter(currentFreeGame, totalFreeGame);
    }

    public showOutro(totalWon: number): void {
        this.freeGameOutro.show(totalWon);
    }

    public override dispose(): void {
        for (const overlay of [this.freeGameCounter, this.freeGameIntro, this.freeGameOutro]) {
            if (overlay) {
                overlay.removeFromParent();
                overlay.destroy({ children: true });
            }
        }
        super.dispose();
    }
}

export { FreeGameScene as FreeGameScence };
