import { Spine } from '@pixi/spine-pixi';
import * as PIXI from 'pixi.js';
import { gsap } from 'gsap';

export class GameBackground extends PIXI.Container {
    public readonly basegameBg: PIXI.Sprite | Spine;
    public readonly freegameBg: PIXI.Sprite | Spine;

    private activeBackground: PIXI.Sprite | Spine;
    private isFreeGame: boolean;
    private cancelPendingTransition?: () => void;

    constructor(
        basegameBg: PIXI.Sprite | Spine,
        freegameBg: PIXI.Sprite | Spine,
        isFreeGame = false,
        private readonly gameAreaW = 700,
        private readonly gameAreaH = 720,
    ) {
        super();
        this.basegameBg = basegameBg;
        this.freegameBg = freegameBg;
        this.isFreeGame = isFreeGame;
        this.activeBackground = isFreeGame ? freegameBg : basegameBg;

        this.fitBackground(basegameBg);
        this.fitBackground(freegameBg);
        basegameBg.alpha = isFreeGame ? 0 : 1;
        basegameBg.visible = !isFreeGame;
        freegameBg.alpha = isFreeGame ? 1 : 0;
        freegameBg.visible = isFreeGame;
        this.addChild(basegameBg, freegameBg);
    }

    public show(isFreeGame = this.isFreeGame, duration = 0.8): Promise<void> {
        this.cancelTransition();

        const incoming = isFreeGame ? this.freegameBg : this.basegameBg;
        const outgoing = this.activeBackground;
        this.isFreeGame = isFreeGame;
        this.activeBackground = incoming;
        incoming.visible = true;

        if (incoming === outgoing && incoming.alpha === 1) {
            return Promise.resolve();
        }

        if (duration <= 0) {
            incoming.alpha = 1;
            if (outgoing !== incoming) {
                outgoing.alpha = 0;
                outgoing.visible = false;
            }
            return Promise.resolve();
        }

        incoming.alpha = incoming === outgoing ? incoming.alpha : 0;
        return new Promise((resolve) => {
            let pending = true;
            const finish = () => {
                if (!pending) return;
                pending = false;
                if (outgoing !== incoming) {
                    outgoing.alpha = 0;
                    outgoing.visible = false;
                }
                this.cancelPendingTransition = undefined;
                resolve();
            };

            this.cancelPendingTransition = () => {
                if (!pending) return;
                pending = false;
                gsap.killTweensOf([incoming, outgoing]);
                incoming.alpha = 1;
                incoming.visible = true;
                if (outgoing !== incoming) {
                    outgoing.alpha = 0;
                    outgoing.visible = false;
                }
                this.cancelPendingTransition = undefined;
                resolve();
            };

            gsap.to(incoming, {
                alpha: 1,
                duration,
                ease: 'power2.inOut',
                onComplete: outgoing === incoming ? finish : undefined,
            });
            if (outgoing !== incoming) {
                gsap.to(outgoing, { alpha: 0, duration, ease: 'power2.inOut', onComplete: finish });
            }
        });
    }

    public hide(isFreeGame = this.isFreeGame, duration = 0.8): Promise<void> {
        this.cancelTransition();

        const target = isFreeGame ? this.freegameBg : this.basegameBg;
        if (!target.visible || target.alpha === 0) {
            return Promise.resolve();
        }

        if (duration <= 0) {
            target.alpha = 0;
            target.visible = false;
            return Promise.resolve();
        }

        return new Promise((resolve) => {
            let pending = true;
            const finish = () => {
                if (!pending) return;
                pending = false;
                target.alpha = 0;
                target.visible = false;
                this.cancelPendingTransition = undefined;
                resolve();
            };

            this.cancelPendingTransition = () => {
                if (!pending) return;
                pending = false;
                gsap.killTweensOf(target);
                target.alpha = 0;
                target.visible = false;
                this.cancelPendingTransition = undefined;
                resolve();
            };

            gsap.to(target, { alpha: 0, duration, ease: 'power2.inOut', onComplete: finish });
        });
    }

    private fitBackground(background: PIXI.Sprite | Spine): void {
        const bounds = background.getLocalBounds();
        if (bounds.width <= 0 || bounds.height <= 0) {
            return;
        }

        const scale = Math.max(this.gameAreaW / bounds.width, this.gameAreaH / bounds.height);
        background.pivot.set(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
        background.scale.set(scale);
        background.position.set(this.gameAreaW / 2, this.gameAreaH / 2);
    }

    private cancelTransition(): void {
        this.cancelPendingTransition?.();
    }
}
