import * as PIXI from 'pixi.js';
import { gsap } from 'gsap';

export type PromoAnimation = 'alpha' | 'land';

export class PromoMessages extends PIXI.Container {
    private readonly promos: PIXI.Container[] = [];
    private readonly restingY = new Map<PIXI.Container, number>();
    private readonly promoMask: PIXI.Graphics;
    private activeIndex = -1;
    private intervalTimer: ReturnType<typeof setInterval> | undefined;

    constructor(
        width: number,
        height: number,
        public readonly animation: PromoAnimation = 'alpha',
        private readonly intervalMs = 5000,
    ) {
        super();
        if (width <= 0 || height <= 0 || intervalMs <= 0) {
            throw new RangeError('Promo dimensions and interval must be positive.');
        }

        this.promoMask = new PIXI.Graphics();
        this.promoMask.rect(0, 0, width, height);
        this.promoMask.fill(0xffffff);
        this.addChild(this.promoMask);
        this.mask = this.promoMask;
    }

    public addPromo(promo: PIXI.Container): void {
        if (this.promos.includes(promo)) {
            throw new Error('This promo has already been added.');
        }

        this.promos.push(promo);
        this.restingY.set(promo, promo.y);
        promo.visible = false;
        this.addChild(promo);

        if (this.activeIndex === -1) {
            this.activeIndex = 0;
            promo.visible = true;
        }
    }

    public start(): void {
        if (this.intervalTimer !== undefined || this.promos.length < 2) {
            return;
        }

        this.intervalTimer = setInterval(() => this.showNextPromo(), this.intervalMs);
    }

    public dispose(): void {
        if (this.intervalTimer !== undefined) {
            clearInterval(this.intervalTimer);
            this.intervalTimer = undefined;
        }
        for (const promo of this.promos) {
            gsap.killTweensOf(promo);
        }
    }

    private showNextPromo(): void {
        const previous = this.promos[this.activeIndex];
        const nextIndex = (this.activeIndex + 1) % this.promos.length;
        const next = this.promos[nextIndex];
        this.activeIndex = nextIndex;

        if (!previous || !next) {
            return;
        }

        next.visible = true;
        const restingY = this.restingY.get(next) ?? next.y;

        if (this.animation === 'alpha') {
            next.alpha = 0;
            gsap.to(next, { alpha: 1, duration: 0.5, ease: 'power2.inOut' });
            gsap.to(previous, {
                alpha: 0,
                duration: 0.5,
                ease: 'power2.inOut',
                onComplete: () => {
                    previous.visible = false;
                    previous.alpha = 1;
                },
            });
            return;
        }

        gsap.to(previous, {
            alpha: 0,
            duration: 0.2,
            ease: 'power1.out',
            onComplete: () => {
                previous.visible = false;
                previous.alpha = 1;
            },
        });
        next.alpha = 1;
        gsap.fromTo(
            next,
            { y: restingY - 50 },
            { y: restingY, duration: 0.7, ease: 'bounce.out' },
        );
    }
}
