import { AssetLoader } from "./assets/AssetLoader";
import { EventDispather, GameEvents } from "./core/EventDispather";
import { GameStateModel } from "./models/GameStateModel";
import { NetworkService, SpinResponse } from "./services/NetworkService";
import * as PIXI from 'pixi.js';
import type { GameScene } from './scene/GameScene';

export type GameSceneId = 'Base_Game' | 'Free_Game';

export abstract class Game {
    public static activeScene: GameScene | null = null;
    private static activeResponse: SpinResponse | undefined;
    private static eventDispatcher: EventDispather = EventDispather.getInstance();
    private static networkService: NetworkService;
    private static stateModel: GameStateModel;
    private static stage: PIXI.Container;
    private static balance = 1000;
    private static bet = 1;
    private static roundWin = 10;
    private currentScene: GameScene | null = null;
    constructor(stage: PIXI.Container) {
        Game.stage = stage;
        Game.networkService = new NetworkService();
        Game.stateModel = new GameStateModel();
        this.initilizeLoading();
    }

    get networkService(): NetworkService {
        return Game.networkService;
    }
    get stateModel(): GameStateModel {
        return Game.stateModel;
    }
    get eventDispatcher(): EventDispather {
        return Game.eventDispatcher;
    }
    public get stage(): PIXI.Container {
        return Game.stage;
    }
    get balance(): number {
        return Game.balance;
    }
    set balance(value: number) {
        Game.balance = value;
    }
    get bet(): number {
        return Game.bet;
    }
    set bet(value: number) {
        Game.bet = value;
    }
    get roundWin(): number {
        return Game.roundWin;
    }
    set roundWin(value: number) {
        Game.roundWin = value;
    }
    get activeResponse():SpinResponse|undefined{
        return Game.activeResponse;
    }
    set activeResponse(value:SpinResponse){
        Game.activeResponse=value;
    }
    protected async initilizeLoading(): Promise<void> {
        const loadingScreen = document.getElementById('loading-screen');
        const loadingBar = document.getElementById('loading-bar');
        const loadingProgress = document.getElementById('loading-progress');
        const loadingTrack = document.getElementById('loading-bar-track');
        const loadingMessage = document.getElementById('loading-message');

        const updateProgress = (progress: number) => {
            const percentage = Math.round(Math.max(0, Math.min(progress, 1)) * 100);
            if (loadingBar) loadingBar.style.width = `${percentage}%`;
            if (loadingProgress) loadingProgress.textContent = `${percentage}%`;
            loadingTrack?.setAttribute('aria-valuenow', String(percentage));
        };

        try {
            await AssetLoader.loadAssets((progress) => {
                if (loadingScreen) loadingScreen.style.display = 'flex';
                updateProgress(progress);
            });
            this.activateScene(this.registerScence('Base_Game'));
            this.resize(window.innerWidth, window.innerHeight);
            loadingScreen?.remove();
        } catch (error) {
            console.error('[Game Startup Error]:', error);
            if (loadingMessage) loadingMessage.textContent = 'Unable to load game. Please refresh to try again.';
            if (loadingProgress) loadingProgress.textContent = '';
            if (loadingBar) loadingBar.style.background = '#ff5c5c';
        }
    }
    protected abstract registerScence(sceneId: GameSceneId, totalFreeGames?: number): GameScene;

    public startFreeGame(totalFreeGames: number): void {
        if (!Number.isInteger(totalFreeGames) || totalFreeGames <= 0) {
            throw new RangeError('Total free games must be a positive integer.');
        }
        if (!this.currentScene) {
            throw new Error('Cannot start free games before the base game scene is initialized.');
        }
        if (!this.stateModel.canSpin()) {
            throw new Error('Cannot start free games while a spin is in progress.');
        }
        if (this.currentScene.sceneId === 'Free_Game') {
            throw new Error('A free game scene is already active.');
        }
        this.activateScene(this.registerScence('Free_Game', totalFreeGames));
    }

    public endFreeGame(): void {
        if (this.currentScene?.sceneId !== 'Free_Game') {
            throw new Error('Cannot end free games when the free game scene is not active.');
        }
        if (!this.stateModel.canSpin()) {
            throw new Error('Cannot end free games while a spin is in progress.');
        }
        this.activateScene(this.registerScence('Base_Game'));
    }

    private activateScene(scene: GameScene): void {
        this.currentScene?.dispose();
        Game.activeScene = null;
        this.currentScene = scene;
        scene.init();
        Game.activeScene = scene;
    }

    public resize(width: number, height: number): void {
        if (Game.activeScene instanceof PIXI.Container) {
            Game.eventDispatcher.emit(GameEvents.GAME_RESIZED, width, height);
        }
    }
}
